#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <zlib.h>

int main(int argc, char **argv) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <gzip_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if (!f) {
        fprintf(stderr, "Cannot open %s\n", argv[1]);
        return 1;
    }

    fseek(f, 0, SEEK_END);
    long fsize = ftell(f);
    fseek(f, 0, SEEK_SET);

    unsigned char *inbuf = malloc(fsize);
    fread(inbuf, 1, fsize, f);
    fclose(f);

    z_stream strm;
    memset(&strm, 0, sizeof(strm));

    int ret = inflateInit2(&strm, MAX_WBITS + 32);
    if (ret != Z_OK) {
        fprintf(stderr, "inflateInit2 failed: %d\n", ret);
        return 1;
    }

    strm.next_in = inbuf;
    strm.avail_in = fsize;

    // Use a heap-allocated buffer of exactly 512 bytes
    // Put guard pages around it
    unsigned char *outbuf = malloc(512);
    memset(outbuf, 0xAB, 512);

    strm.next_out = outbuf;
    strm.avail_out = 512;

    ret = inflate(&strm, Z_SYNC_FLUSH);
    printf("inflate returned: %d\n", ret);
    printf("avail_in: %u, avail_out: %u\n", strm.avail_in, strm.avail_out);
    printf("total_out: %lu\n", strm.total_out);

    // Check if data was written past the buffer
    for (int i = 458; i < 512; i++) {
        if (outbuf[i] != 0xAB) {
            printf("Buffer modified at offset %d: 0x%02x (was 0xAB)\n", i, outbuf[i]);
        }
    }

    inflateEnd(&strm);
    free(inbuf);
    free(outbuf);
    return 0;
}
EOF
